        if (isAncestor(a, b) || isAncestor(b, a)) continue
        const pa = worldOf(a), pb = worldOf(b)
        const overlapX = pa.x < pb.x + b.size.x && pa.x + a.size.x > pb.x
        const overlapY = pa.y < pb.y + b.size.y && pa.y + a.size.y > pb.y
