  const HIERARCHY: Record<number, number[]> = {}
  const EDGE_IDX: [number, number | null, string | null, number, number | null, string | null][] = [[0,0,"P1_1",8,0,"P9_W1"],[1,0,"P2_1",8,2,"P9_N1"],[2,0,"P3_1",8,3,"P9_N2"],[3,0,"P4_1",8,5,"P9_N4"],[8,1,"P9_E1",7,0,"P8_1"],[8,4,"P9_N3",4,0,"P5_1"],[8,6,"P9_N5",5,0,"P6_1"],[8,7,"P9_N6",6,0,"P7_1"]]
