    graph.setProperty('org.eclipse.elk.direction', "RIGHT")
    graph.setProperty('org.eclipse.elk.layered.edgeLabels.sideSelection', "ALWAYS_DOWN")
    graph.setProperty('org.eclipse.elk.randomSeed', 1)

