    const oracle = JSON.parse(readFileSync(new URL('../../../test-resources/jar-oracle/tests__layered__edge_label_placement__layerSelection_center_02.json', import.meta.url), 'utf8'))
    expect(oracle.hash, 'jar oracle 过期/缺失, 请重跑 node scripts/generate-jar-oracle.mjs').toBe('448b1e0d5315d7fb')
