    const worldOf = (n: LNode): { x: number; y: number } => {
      let wx = n.position.x, wy = n.position.y
      let g = n.getGraph()
      while (g !== null && g !== graph) {
        const parent = g.getParentNode()
        if (parent === null) break
        wx += parent.position.x
        wy += parent.position.y
        g = parent.getGraph()
      }
      return { x: wx, y: wy }
    }
