    graph.setProperty('org.eclipse.elk.direction', "DOWN")
    graph.setProperty('org.eclipse.elk.layered.edgeLabels.sideSelection', "SMART_UP")
    graph.setProperty('org.eclipse.elk.randomSeed', 1)

