    if (false) {
      for (const n of nodeOf.values()) {
        expect(Number.isFinite(n.position.x)).toBe(true)
        expect(Number.isFinite(n.position.y)).toBe(true)
      }
      return
    }

    // L1 (M3): 与 ELK Java 0.12.0 jar oracle 坐标级差分 (容差 ε = 2).
    // oracle 坐标相对父块 (jar getX/getY); ggn 子图节点坐标同样相对父 → 直接对比, 无需世界坐标累加.
    const oracle = JSON.parse(readFileSync(new URL('../../../test-resources/jar-oracle/tests__layered__high_degree_nodes__Fan.json', import.meta.url), 'utf8'))
