  const PORT_CONSTRAINTS: (string | null)[] = ["FREE","FREE","FREE","FREE"]
  const NODE_PORTS: { id: string; x: number; y: number; w: number; h: number; side: string | null; index: number | null; borderOffset: number | null; labels: { text: string; x: number; y: number; width: number; height: number }[] }[][] = [[{"id":"n1_p1","x":0,"y":0,"w":5,"h":5,"side":null,"index":null,"borderOffset":null,"labels":[]}],[{"id":"n2_p1","x":0,"y":0,"w":5,"h":5,"side":null,"index":null,"borderOffset":null,"labels":[]},{"id":"n2_p2","x":0,"y":0,"w":5,"h":5,"side":null,"index":null,"borderOffset":null,"labels":[]}],[{"id":"n2_1_p1","x":0,"y":0,"w":5,"h":5,"side":null,"index":null,"borderOffset":null,"labels":[]},{"id":"n2_1_p2","x":0,"y":0,"w":5,"h":5,"side":null,"index":null,"borderOffset":null,"labels":[]}],[{"id":"n3_p1","x":0,"y":0,"w":5,"h":5,"side":null,"index":null,"borderOffset":null,"labels":[]}]]
